function finalEnding(s) {
  if (s.o >= 60 && s.f >= 60) return 'star';
  if (s.m >= 65 && s.f <= 35) return 'valley';
  if (s.m >= 65 && s.o < 40) return 'factory';
  if (s.f >= 65 && s.o < 40) return 'idol';
  if (s.o >= 65 && s.f < 35) return 'genius';
  if (s.l >= 65 && s.m < 40) return 'tavern';
  return 'still';
}

